UPDATE courses SET
    course_description = '<h4>Course Overview</h4> <p><strong>FNS60222 – Advanced Diploma of Accounting</strong> reflects the role of individuals working in accounting and seeking professional recognition, including tax agents, accounts managers and business analysts; and to employees performing a range of accounts management tasks for organisations in a range of industries. At this level individuals are expected to apply theoretical and technical skills in a range of situations and to display initiative and judgement in planning activities. They have autonomy in performing complex operations and can be responsible for planning, coordinating and evaluating the work of others within broad but generally well-defined parameters.</p>',
    course_duration_per_week = 52,
    offshore_tuition_fee = 16000,
    onshore_tuition_fee = 14000,
    enrolment_fee = 200,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4> <p>Prior to commencing this qualification an individual must have completed the following qualifications (or equivalent).</p> <ul><li>FNS50222 Diploma of Accounting; or its superseded version FNS50217 Diploma of Accounting or equivalent, provided the listed elective unit BSBTEC402 Design and produce complex spreadsheets (or equivalent) has been completed by those seeking to enrol.</li> </ul><p>Students must be 18 years old and above.</p> <p>Successful completion of Australian Year 12 or Australian equivalent is mandatory.</p> <p>English requirement</p><p>A minimum of IELTS 6.0 or equivalent is required.</p><p>For more information regarding the commonly acceptable types of English language proficiency evidence, along with the verification methods, please <a href="https://reachcollege.edu.au/courses/english/">click here</a></p><p>Student Requirements</p><p>Students are required to have their own laptop prior to the commencement of their course.</p><p>The minimum requirements for the specification of laptops can be found in the Student Equipment Required section below.</p><p>Language, Literacy, Numeracy, and Digital skills (LLND)​</p><p>Prior to enrolment, all prospective students are required to complete a compulsory Language, Literacy, Numeracy and Digital (LLND) assessment. This assessment is completed as part of the pre-enrolment process through the LLND Portal – <a href="https://myllnd.com/login/">myllnd.com/login/</a></p><p>The LLND assessment helps identify whether a student may need additional support during their studies and ensures they are placed in a course that is appropriate for their skill level. Assessments are aligned with the Australian Core Skills Framework (ACSF) and include language, literacy, numeracy and digital skills.</p><p>Students must complete their LLND assessment via the LLND Portal before they can be formally enrolled. Further instructions on how to access and complete the assessment will be provided to prospective students as part of the pre-enrolment process.</p>',
    apply_form = 'https://reachcollege.edu.au/courses/business/advanced-diploma-of-accounting/',
    updated_at = NOW()
