    course_description = '<h4>Course Overview</h4> <p><strong>BSB60120 – Advanced Diploma of Business</strong> reflects the role of individuals with significant experience in a senior administrative role who are seeking to develop expertise across a wider range of business functions.</p> <p>The qualification is suited to individuals who possess significant theoretical business skills and knowledge and wish to consolidate and build pathways to further educational or employment opportunities.</p>',
