UPDATE courses SET
    course_description = '<h4>Course Overview</h4> <p><strong>BSB80120 – Graduate Diploma of Management (Learning)</strong> reflects the role of individuals who apply highly specialised knowledge and skills in the field of organisational learning and capability development. Individuals in these roles generate and evaluate complex ideas. They also initiate, design and execute major learning and development functions within an organisation. Typically, they would have full responsibility and accountability for the personal output and work of others.</p> <p>This qualification may apply to leaders and managers in an organisation where learning is used to build organisational capability. The job roles that relate to this qualification may also include RTO Manager and RTO Director.</p>',
    course_duration_per_week = 52,
    offshore_tuition_fee = 16000,
    onshore_tuition_fee = 13000,
    enrolment_fee = 200,
    materials_fee = NULL,
