UPDATE courses SET
    course_description = '<h4>Course Overview</h4> <p><strong>BSB80320 – Graduate Diploma of Strategic Leadership </strong>reflects the role of individuals who apply advanced knowledge and skills in a range of strategic leadership and management roles.</p> <p>Individuals at this level make high level autonomous decisions and use initiative and judgement to plan and implement a range of leadership and management functions in varied contexts. They have full responsibility and accountability for personal outputs and for the work or function of others.</p> <p>They use cognitive and creative skills to review, critically analyse, consolidate and synthesise knowledge, in order to generate ideas and provide solutions to complex problems. They use communication skills to demonstrate their understanding of theoretical concepts and to transfer knowledge and ideas to others.</p>',
    course_duration_per_week = 52,
    offshore_tuition_fee = 16000,
    onshore_tuition_fee = 13000,
    enrolment_fee = 200,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4> <p>Please be advised that students must attend a pre-consultation interview before enrolling in this qualification. This interview is conducted to assess their suitability for the course.</p> <p>Students must be 18 years old and above.</p> <p><strong>Academic requirement:</strong></p> <p><strong>Entry to this qualification is limited to those who:</strong></p> <p>Have completed a Diploma or Advanced Diploma qualification in related fields of study and 3 years equivalent full-time relevant workplace experience at a significant level of leadership and management responsibility and/or complexity in an enterprise</p> <p>or</p> <p>Have completed a Bachelor degree in related fields of study and 2 years equivalent full-time relevant workplace experience at a significant level of leadership and management responsibility and/or complexity in an enterprise.</p> <p>or</p> <p>Have five years equivalent full-time relevant workplace experience at a significant level of leadership and management responsibility and/or complexity in an enterprise.</p> <p>English requirement</p><p>A minimum of IELTS 6.5 or equivalent is required.</p><p>For more information regarding the commonly acceptable types of English language proficiency evidence, along with the verification methods, please <a href="https://reachcollege.edu.au/courses/english/">click here</a></p><p>Student Requirements</p><p>Students are required to have their own laptop prior to the commencement of their course.</p><p>The minimum requirements for the specification of laptops can be found in the Student Equipment Required section below.</p><p>Language, Literacy, Numeracy, and Digital skills (LLND)​</p><p>Prior to enrolment, all prospective students are required to complete a compulsory Language, Literacy, Numeracy and Digital (LLND) assessment. This assessment is completed as part of the pre-enrolment process through the LLND Portal – <a href="https://myllnd.com/login/">myllnd.com/login/</a></p><p>The LLND assessment helps identify whether a student may need additional support during their studies and ensures they are placed in a course that is appropriate for their skill level. Assessments are aligned with the Australian Core Skills Framework (ACSF) and include language, literacy, numeracy and digital skills.</p><p>Students must complete their LLND assessment via the LLND Portal before they can be formally enrolled. Further instructions on how to access and complete the assessment will be provided to prospective students as part of the pre-enrolment process.</p>',
    apply_form = 'https://reachcollege.edu.au/courses/business/graduate-diploma-of-strategic-leadership/',
    updated_at = NOW()
WHERE cricos_course_code = '106650G';
UPDATE courses SET
    course_description = '<h4>Course Overview</h4> <p><strong>CHC62015 – Advanced Diploma Of Community Sector Management </strong>reflects the role of workers who are middle managers or managers across a range of community sector organisations. These people work independently and report to executive management, directors or boards of management. They undertake a range of functions requiring the application of knowledge and skills to achieve results in line with the organisation’s goals and strategic directions.</p> <p>At this level, workers have responsibility for planning and monitoring service delivery, recruitment and performance management of other paid or unpaid workers, managing risk and contributing to continuous improvement within the scope of their specific role. This may include management of a specific program or project or broader management of a community-based organisation, early childhood education service, not-for-profit organisation or community centre.</p> <p>This qualification does not require any Student Work Placement hours.</p>',
    course_duration_per_week = 52,
    offshore_tuition_fee = 16000,
    onshore_tuition_fee = 14000,
