UPDATE courses SET
    course_description = '<h4>Course Overview</h4> <p><strong>SIT60322 – Advanced Diploma of Hospitality Management</strong> reflects the role of highly skilled senior managers who use a broad range of hospitality skills combined with specialised managerial skills and substantial knowledge of industry to coordinate hospitality operations. They operate with significant autonomy and are responsible for making strategic business management decisions.</p> <p>This qualification provides a pathway to work in any hospitality industry sector and for a diversity of employers including restaurants, hotels, motels, catering operations, clubs, pubs, cafés, and coffee shops. This qualification allows for multi-skilling and for specialisation in accommodation services, cookery, food and beverage and gaming.</p> <p><strong>Possible job titles include:</strong></p> <ul><li>area manager or operations manager</li> <li>café owner or manager</li> <li>club secretary or manager</li> <li>executive chef</li> <li>executive housekeeper</li> <li>executive sous chef</li> <li>food and beverage manager</li> <li>head chef</li> <li>motel owner or manager</li> <li>rooms division manager</li> </ul><p>Completion of an REACH qualification does not guarantee an employment outcome.</p> <p>No occupational licensing, certification or specific legislative requirements apply to this qualification at the time of publication.</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 24000,
    onshore_tuition_fee = 22000,
